#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Migratiehulp voor #19 (repo-transfer); wordt na afronding opgeruimd.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

OLD_REPO="jypma-prlg/nl-portal"
NEW_REPO="pinkroccade/nl-portal"
ORG="pinkroccade"
TEAM_SLUG="mijngemeente-core"
STATE_DIR=".transfer"
ENV_FILE="$STATE_DIR/state.env"
mkdir -p "$STATE_DIR"

# snap DIR REPO: legt namen van secrets/variabelen/environments/rulesets/labels/hooks en
# de belangrijkste repo-instellingen vast, zodat voor en na met diff vergeleken kunnen worden.
snap() {
  local dir="$1" repo="$2"
  mkdir -p "$dir"
  gh api --paginate "repos/$repo/actions/secrets" --jq '.secrets[].name' 2>/dev/null | sort > "$dir/secrets.txt" || true
  gh api --paginate "repos/$repo/actions/variables" --jq '.variables[].name' 2>/dev/null | sort > "$dir/variables.txt" || true
  gh api "repos/$repo/environments" --jq '.environments[].name' 2>/dev/null | sort > "$dir/environments.txt" || true
  gh api "repos/$repo/rulesets" --jq '.[].name' 2>/dev/null | sort > "$dir/rulesets.txt" || true
  gh api "repos/$repo/branches/main/protection" --jq '.required_status_checks.contexts[]' 2>/dev/null | sort > "$dir/main-protection.txt" || true
  gh api --paginate "repos/$repo/labels" --jq '.[].name' 2>/dev/null | sort > "$dir/labels.txt" || true
  gh api "repos/$repo/hooks" --jq '.[].config.url' 2>/dev/null | sort > "$dir/hooks.txt" || true
  gh api "repos/$repo" --jq '"visibility=\(.visibility)", "default_branch=\(.default_branch)", "has_issues=\(.has_issues)", "allow_squash_merge=\(.allow_squash_merge)", "allow_merge_commit=\(.allow_merge_commit)", "allow_rebase_merge=\(.allow_rebase_merge)", "delete_branch_on_merge=\(.delete_branch_on_merge)", "allow_auto_merge=\(.allow_auto_merge)"' 2>/dev/null > "$dir/settings.txt" || true
  say "vastgelegd in $dir/: $(find "$dir" -name '*.txt' | wc -l | tr -d ' ') bestanden"
}

# ── Fase 1: voor de transfer ──────────────────────────────────────────────
phase_voor() {
  TOTAL_STAGES=4
  banner "Repo-transfer #19, fase 1: voorbereiding (nog niets wordt verplaatst)"

  stage "Controle van de voorwaarden"
  local problems=0
  if gh auth status >/dev/null 2>&1; then say "✓ gh is ingelogd"; else warn "gh is niet ingelogd (gh auth login)"; problems=$((problems+1)); fi
  case "$(git remote get-url origin 2>/dev/null)" in
    *"$OLD_REPO"*) say "✓ origin wijst naar $OLD_REPO" ;;
    *) warn "origin wijst niet naar $OLD_REPO"; problems=$((problems+1)) ;;
  esac
  [[ "$(git branch --show-current)" == "main" ]] && say "✓ je staat op main" || { warn "je staat niet op main"; problems=$((problems+1)); }
  [[ -z "$(git status --short)" ]] && say "✓ werkboom is schoon" || { warn "werkboom heeft wijzigingen"; problems=$((problems+1)); }
  git fetch -q origin || true
  [[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main 2>/dev/null)" ]] && say "✓ main is actueel" || { warn "main loopt niet gelijk met origin/main"; problems=$((problems+1)); }
  if git grep -qE "_publish-(be|fe)-s3|repository == 'pinkroccade/nl-portal'" -- .github; then
    warn "de CI-voorbereidings-PR (S3 weg, guards op repository_owner) staat nog niet op main"; problems=$((problems+1))
  else
    say "✓ CI-voorbereiding staat op main"
  fi
  if (( problems )); then
    warn "$problems punt(en) om te bekijken"
    confirm "Toch doorgaan?" || exit 1
  fi

  stage "Doel-organisatie en team"
  local role team_id
  role=$(gh api "user/memberships/orgs/$ORG" --jq .role 2>/dev/null || true)
  if [[ -n "$role" ]]; then say "✓ jouw rol in $ORG: $role"; else warn "geen lidmaatschap van $ORG gevonden"; fi
  if gh api "repos/$NEW_REPO" >/dev/null 2>&1; then
    warn "$NEW_REPO bestaat al: de transfer zou mislukken"; confirm "Toch doorgaan?" || exit 1
  else
    say "✓ de naam $NEW_REPO is vrij"
  fi
  team_id=$(gh api "orgs/$ORG/teams/$TEAM_SLUG" --jq .id 2>/dev/null || true)
  if [[ -n "$team_id" ]]; then write_env TEAM_ID "$team_id"; else warn "team $TEAM_SLUG niet gevonden; maak het aan in $ORG"; exit 1; fi

  stage "Momentopname van de huidige repo"
  snap "$STATE_DIR/voor" "$OLD_REPO"
  say "Open pull requests (die gaan mee):"
  gh pr list --repo "$OLD_REPO" --json number,title --jq '.[] | "  #\(.number) \(.title)"' || true
  say "Lopende workflow-runs (wacht tot ze klaar zijn):"
  gh run list --repo "$OLD_REPO" --status in_progress --json name --jq '.[] | "  \(.name)"' || true
  note "De wekelijkse checks draaien zondag 18:00-23:00 UTC; plan de transfer daarbuiten."

  stage "Handmatig: organisatie-instellingen"
  say "Controleer in $ORG dat Actions de gebruikte acties toestaat."
  open_url "https://github.com/organizations/$ORG/settings/actions"
  say "De repo gebruikt acties van deze eigenaren:"
  git grep -ho "uses: [^/@ ]*/" -- .github | sort -u | sed 's/^/    /'
  step "Kies 'Allow all actions' of zet deze eigenaren op de lijst (let ook op 'Require actions to be pinned to a commit SHA')."
  step "GitHub App: stap 1-5 uit de instructie (App aanmaken, Client ID, private key) heb je al gedaan; bewaar het .pem-bestand tot fase 3."
  pause "Gedaan? Dan kun je 'mise run transfer:uitvoeren' draaien."
  finish
}

# ── Fase 2: de transfer zelf ──────────────────────────────────────────────
phase_uitvoeren() {
  TOTAL_STAGES=3
  banner "Repo-transfer #19, fase 2: uitvoeren"

  stage "Laatste bevestiging"
  local team_id; team_id=$(_existing TEAM_ID || true)
  [[ -n "$team_id" ]] || { warn "TEAM_ID ontbreekt: draai eerst 'mise run transfer:voor'"; exit 1; }
  say "Van:   $OLD_REPO"
  say "Naar:  $NEW_REPO (naam blijft gelijk)"
  say "Team:  $TEAM_SLUG (id $team_id) krijgt toegang bij de transfer"
  warn "Dit kan niet met een druk op de knop terug; GitHub zet wel een redirect van de oude URL."
  ask CONFIRM_NAME "Typ de reponaam (nl-portal) om te bevestigen:"
  [[ "$CONFIRM_NAME" == "nl-portal" ]] || { warn "bevestiging komt niet overeen, afgebroken"; exit 1; }

  stage "Transfer uitvoeren"
  gh api -X POST "repos/$OLD_REPO/transfer" -f new_owner="$ORG" -F "team_ids[]=$team_id" --jq '.full_name' || { warn "transfer mislukt; doe het handmatig via Settings > General > Danger Zone"; exit 1; }
  say "Wachten tot $NEW_REPO bereikbaar is..."
  local i
  for i in $(seq 1 24); do
    if gh api "repos/$NEW_REPO" --jq .full_name >/dev/null 2>&1; then say "✓ $NEW_REPO bestaat"; break; fi
    sleep 5
    [[ $i -eq 24 ]] && { warn "nog niet zichtbaar; controleer of de org de transfer moet accepteren"; exit 1; }
  done

  stage "Lokale remote omzetten"
  git remote set-url origin "git@github.com:$NEW_REPO.git"
  git fetch origin --prune
  gh repo set-default "$NEW_REPO" >/dev/null 2>&1 || true
  git remote -v
  say "✓ Klaar. Draai nu 'mise run transfer:na'."
  finish
}

# ── Fase 3: na de transfer ────────────────────────────────────────────────
phase_na() {
  TOTAL_STAGES=9
  banner "Repo-transfer #19, fase 3: inrichten en controleren"
  local team_id; team_id=$(_existing TEAM_ID || true)

  stage "Vergelijk met de situatie van voor de transfer"
  if [[ "$(git remote get-url origin)" != *"$NEW_REPO"* ]]; then
    git remote set-url origin "git@github.com:$NEW_REPO.git"; say "origin omgezet naar $NEW_REPO"
  fi
  gh repo set-default "$NEW_REPO" >/dev/null 2>&1 || true
  snap "$STATE_DIR/na" "$NEW_REPO"
  local f any=0
  for f in "$STATE_DIR"/voor/*.txt; do
    if diff -u "$f" "$STATE_DIR/na/$(basename "$f")" >/dev/null 2>&1; then
      say "✓ $(basename "$f" .txt): ongewijzigd"
    else
      any=1; warn "$(basename "$f" .txt): verschilt"; diff -u "$f" "$STATE_DIR/na/$(basename "$f")" | tail -n +3 | sed 's/^/      /' || true
    fi
  done
  (( any )) && note "Verschillen (bijv. ontbrekende secrets) pakken de volgende stappen op."
  pause "Verder?"

  stage "Teamrechten"
  gh api -X PUT "orgs/$ORG/teams/$TEAM_SLUG/repos/$NEW_REPO" -f permission=push >/dev/null && say "✓ $TEAM_SLUG heeft write-rechten" || warn "kon teamrechten niet zetten"
  gh api "repos/$NEW_REPO/teams" --jq '.[] | "  \(.slug): \(.permission)"' || true
  note "Jouw eigen admin-rechten regel je via Settings > Collaborators and teams."

  stage "Environment 'release' met goedkeurders"
  if grep -qx release "$STATE_DIR/na/environments.txt" 2>/dev/null; then
    say "✓ environment 'release' bestaat al"
  elif [[ -n "$team_id" ]] && confirm "Environment 'release' aanmaken met $TEAM_SLUG als goedkeurder (gate voor releases)?"; then
    printf '{"reviewers":[{"type":"Team","id":%s}]}' "$team_id" | gh api -X PUT "repos/$NEW_REPO/environments/release" --input - >/dev/null && say "✓ aangemaakt" || warn "aanmaken mislukt; doe het handmatig onder Settings > Environments"
  else
    SKIPPED+=("environment 'release' (Settings > Environments)")
  fi

  stage "Ontbrekende secrets aanvullen"
  local name have
  have=$(gh secret list --repo "$NEW_REPO" --json name --jq '.[].name' 2>/dev/null || true)
  for name in SONARCLOUD_TOKEN STRIX_LLM LLM_API_KEY LLM_API_BASE; do
    if grep -qx "$name" <<<"$have"; then say "✓ $name aanwezig"; continue; fi
    if confirm "$name ontbreekt. Nu invoeren?"; then
      local val=""; ask_secret val "Waarde voor $name:"; set_secret "$name" "$val"
    else
      SKIPPED+=("secret $name")
    fi
  done
  note "AWS_*, SONATYPE_*, GPG_* en NPM_PUBLISH_TOKEN zijn niet nodig zolang PUBLISH_LIBRARIES uit staat."

  stage "GitHub App koppelen voor releases"
  say "Nodig voor de eerste RC of release (branch release/<major>.x, tag en GitHub Release)."
  if confirm "App nu koppelen?"; then
    open_url "https://github.com/organizations/$ORG/settings/apps"
    step "Installeer de App: Install App > $ORG > Only select repositories > nl-portal."
    local cid="" pem=""
    ask cid "Client ID van de App:"
    ask pem "Pad naar het .pem-bestand:"
    set_secret NL_PORTAL_APP_CLIENT_ID "$cid"
    if [[ -f "$pem" ]]; then set_secret NL_PORTAL_APP_PRIVATE_KEY "$(cat "$pem")"; else warn "bestand niet gevonden: $pem"; SKIPPED+=("secret NL_PORTAL_APP_PRIVATE_KEY"); fi
    open_url "https://github.com/$NEW_REPO/settings/rules"
    step "Open ruleset 'release-lines-require-ci' > Bypass list > Add bypass > kies de App > Always > Save."
    step "Verwijder het .pem-bestand lokaal."
    pause "Klaar?"
  else
    SKIPPED+=("GitHub App koppelen (secrets NL_PORTAL_APP_*, bypass op ruleset release-lines-require-ci)")
  fi

  stage "Renovate en SonarCloud"
  open_url "https://github.com/apps/renovate/installations/new"
  step "Renovate: kies $ORG > Only select repositories > nl-portal > Install. Daarna verschijnt binnen minuten het issue 'Dependency Dashboard'."
  open_url "https://sonarcloud.io/organizations/$ORG/projects"
  step "SonarCloud: open pinkroccade_nl-portal-backend en pinkroccade_nl-portal-frontend, dan Administration > General Settings > Repository binding, en kies $NEW_REPO."
  step "Controleer dat de SonarCloud GitHub App op $ORG toegang heeft tot nl-portal."
  note "Menunamen in SonarCloud kunnen iets afwijken; zoek de koppeling met de repository."
  pause "Gedaan?"

  stage "Private vulnerability reporting"
  say "Laat buitenstaanders kwetsbaarheden privé melden via het tabblad Security."
  if confirm "Nu aanzetten?"; then
    gh api -X PUT "repos/$NEW_REPO/private-vulnerability-reporting" >/dev/null && say "✓ aangezet" || { warn "via API mislukt"; open_url "https://github.com/$NEW_REPO/settings/security_analysis"; step "Zet 'Private vulnerability reporting' aan."; pause "Gedaan?"; }
  else
    SKIPPED+=("private vulnerability reporting aanzetten")
  fi
  note "De tekst in SECURITY.md blijft ticket #15."

  stage "Verwijzingen omzetten naar $NEW_REPO"
  if confirm "Nieuwe branch docs/verwijzingen-pinkroccade-19 aanmaken en alle verwijzingen omzetten?"; then
    git switch -c docs/verwijzingen-pinkroccade-19 origin/main
    git grep -lI "$OLD_REPO" | xargs -r sed -i "s#$OLD_REPO#$NEW_REPO#g"
    sed -i 's#https://github.com/nl-portal/nl-portal-backend-libraries#https://github.com/'"$NEW_REPO"'#; s#git@github.com:nl-portal/nl-portal-backend-libraries.git#git@github.com:'"$NEW_REPO"'.git#' backend/build.gradle.kts
    git diff --stat | tail -1
    say "Nog te herschrijven (staat nog 'jypma-prlg' in?):"
    git grep -nI "jypma-prlg" || say "  ✓ geen verwijzingen meer"
    step "Herschrijf de zin 'specifiek voor deze fork' in site/development/workflows/periodic-checks.md."
    step "Controleer 'git diff', commit en open een PR (type docs:)."
    pause "Klaar?"
  else
    SKIPPED+=("verwijzingen omzetten (jypma-prlg naar pinkroccade)")
  fi

  stage "Acceptatiechecks"
  if confirm "Geplande workflows nu handmatig starten (snapshot, dependency-check, frontend-vulnerability-scan, periodic-maintenance)?"; then
    local wf
    for wf in build-and-publish-snapshot dependency-check frontend-vulnerability-scan periodic-maintenance; do
      gh workflow run "$wf.yml" --ref main && say "✓ $wf gestart" || warn "$wf niet gestart"
    done
    open_url "https://github.com/$NEW_REPO/actions"
  fi
  say "Handmatig afvinken:"
  step "Test-PR openen: check 'ci-required' wordt groen."
  step "Snapshot-run groen; images onder https://github.com/orgs/$ORG/packages zijn publiek en gekoppeld aan de repo (cosign verify zit in de job)."
  step "Dependency Dashboard (Renovate) en SonarCloud-analyse op main zichtbaar."
  step "Pas nadat de App bestaat: een RC-dry-run (build-and-publish-release-candidate)."
  step "Daarna: ticket aanmaken/afronden voor het opruimen van deze wizard (scripts/transfer, mise transfer:*, .gitignore)."
  finish
}

case "${1:-}" in
  voor)      phase_voor ;;
  uitvoeren) phase_uitvoeren ;;
  na)        phase_na ;;
  *) echo "Gebruik: transfer-wizard.sh voor|uitvoeren|na   (of: mise run transfer:voor|uitvoeren|na)" >&2; exit 2 ;;
esac

}

run_wizard "$@"; exit
